#include <iostream>
#include <vector>
#include <string>
#include <map>
#include <set>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string begin;
    string end;
    cin >> begin >> end;
    long long k;
    cin >> k;
    vector<string> words(k);
    for (int i = 0; i < k; i++) cin >> words[i];

    set<string> known(words.begin(), words.end());
    map<string, vector<string>> buckets;
    set<string> all = known;
    all.insert(begin);
    for (const string& word : all) {
        for (size_t i = 0; i < word.size(); i++) {
            string pattern = word;
            pattern[i] = '*';
            buckets[pattern].push_back(word);
        }
    }
    map<string, int> dist;
    dist[begin] = 1;
    vector<string> queue = {begin};
    for (size_t q = 0; q < queue.size(); q++) {
        string word = queue[q];
        for (size_t i = 0; i < word.size(); i++) {
            string pattern = word;
            pattern[i] = '*';
            vector<string> bucket = buckets[pattern];
            buckets[pattern].clear();
            for (const string& other : bucket) {
                if (!dist.count(other)) {
                    dist[other] = dist[word] + 1;
                    queue.push_back(other);
                }
            }
        }
    }
    cout << (known.count(end) && dist.count(end) ? dist[end] : 0) << "\n";

    return 0;
}

